	--temp##v1.99
	
		update transactions set p_date=date_ where p_date is null and 0>=bill_id
		and (date(strftime('%Y-%m-%d',substr( date_,7,4)||'-' ||substr( date_,4,2)||'-'||substr( date_,1,2) )) !=
		(select ifnull(max(date_),date(date(strftime('%Y-%m-%d',substr(transactions.date_,7,4)||'-' ||substr(transactions.date_,4,2)||'-'||substr(transactions.date_,1,2) )),'-1 day'))
		from closing_year))
		and ROWID in(select b.rowid from transactions b where b.p_date is null and 0>=b.bill_id
		and (date(strftime('%Y-%m-%d',substr( b.date_,7,4)||'-' ||substr( b.date_,4,2)||'-'||substr( b.date_,1,2) )) !=
		(select ifnull(max(date_),date(date(strftime('%Y-%m-%d',substr( b.date_,7,4)||'-' ||substr( b.date_,4,2)||'-'||substr( b.date_,1,2) )),'-1 day'))
		from closing_year))
		limit 100);
	



	
