	--update null daily transactoins number
	update transactions
		set p_ref_no=p_id
		where bill_id=-2 and p_ref_no='';
	

	update bills
		set bill_no2=(select count(*) from bills b
		where b.id
		--less than char.
		<=bills.id and b.tr_type=bills.tr_type  and b.is_back=bills.is_back
		and b.br_id=bills.br_id  )
		where bill_no2 =0;
	

	-- TEMP to fetch bill_no to transactions table
	
		update transactions
		set p_ref_no=(select bill_no2 from bills where id=bill_id)
		where bill_id>0 and p_ref_no is null;
	

