	--fix negative numbers
	update transactions set out=abs(out) where out!=abs(out) and not (out>0)
		and (date(strftime('%Y-%m-%d',substr( date_,7,4)||'-' ||substr( date_,4,2)||'-'||substr( date_,1,2) )) !=
		(select ifnull(max(date_),date(date(strftime('%Y-%m-%d',substr(transactions.date_,7,4)||'-' ||substr(transactions.date_,4,2)||'-'||substr(transactions.date_,1,2) )),'-1 day'))
		from closing_year)); 
	
		create table if not exists closing_year
		(id integer primary key autoincrement,date_ text, cnt real default 0,
		now_ text default (strftime('%Y-%m-%d','now')));
	

	-- Prevent unkown transactions
	--2024-01 or NEW.cus_id=ifnull(NEW.t_cus_id,0) NOT Tested till now
	drop TRIGGER if exists prevent_invalid_tr; 
	
		CREATE TRIGGER prevent_invalid_tr
		BEFORE INSERT  ON transactions
		FOR EACH ROW
		WHEN (NEW.cus_id is null or not(NEW.out*1>=0) or NEW.cus_id=ifnull(NEW.t_cus_id,0)
		and (select is_active from trigger_flags)=1
		)
		BEGIN
		SELECT RAISE(ABORT, 'ERROR:Invalid Transaction') ;
		END;
	
	--refresh opening balance to be adapted with account#13
	
		update transactions set bill_id=-1 where bill_id=-1 and t_cus_id is null;
	

	-- Closed Year constaints --Transactions--Bills--Items
	--########### Begin
	
		CREATE TRIGGER if not exists closing_year_update_tr
		BEFORE update  ON transactions
		FOR EACH ROW
		WHEN (date(strftime('%Y-%m-%d',substr( OLD.date_,7,4)||'-' ||substr( OLD.date_,4,2)||'-'||substr( OLD.date_,1,2) ))<=
		(select ifnull(max(date_),date(date(strftime('%Y-%m-%d',substr( OLD.date_,7,4)||'-' ||substr( OLD.date_,4,2)||'-'||substr( OLD.date_,1,2) )),'-1 day')) from closing_year))
		BEGIN
		SELECT RAISE(ABORT, 'CLOSED YEAR') ;
		END;

	

	--recreate in closing year(drop then recreate)
	
		CREATE TRIGGER if not exists closing_year_delete_tr
		BEFORE delete  ON transactions
		FOR EACH ROW
		WHEN (date(strftime('%Y-%m-%d',substr( OLD.date_,7,4)||'-' ||substr( OLD.date_,4,2)||'-'||substr( OLD.date_,1,2) ))<=
		(select ifnull(max(date_),date(date(strftime('%Y-%m-%d',substr( OLD.date_,7,4)||'-' ||substr( OLD.date_,4,2)||'-'||substr( OLD.date_,1,2) )),'-1 day')) from closing_year))
		BEGIN
		SELECT RAISE(ABORT, 'CLOSED YEAR') ;
		END;

	
	
		CREATE TRIGGER if not exists closing_year_insert_tr
		BEFORE insert  ON transactions
		FOR EACH ROW
		WHEN (date(strftime('%Y-%m-%d',substr( NEW.date_,7,4)||'-' ||substr( NEW.date_,4,2)||'-'||substr( NEW.date_,1,2) ))
		<=
		(select ifnull(max(date_),date(date(strftime('%Y-%m-%d',substr( NEW.date_,7,4)||'-'
		||substr( NEW.date_,4,2)||'-'||substr( NEW.date_,1,2) )),'-1 day')) from closing_year))
		BEGIN
		SELECT RAISE(ABORT, 'CLOSED YEAR') ;
		END;

	
	
		CREATE TRIGGER if not exists closing_year_update_bills
		BEFORE update ON bills
		FOR EACH ROW
		WHEN (date(OLD.date_)<=
		(select ifnull(max(date_),date(OLD.date_,'-1 day')) from closing_year))
		BEGIN
		SELECT RAISE(ABORT, 'CLOSED YEAR') ;
		END;
	
	--v195 paid is large than bill amount
	drop trigger if exists paid_amount_update_bills
	
		CREATE TRIGGER if not EXISTS paid_amount_update_bills
		BEFORE update ON bills
		FOR EACH ROW
		WHEN (NEW.paid_amount>NEW.amount and NEW.tr_type in(1,2) )
		BEGIN
		SELECT RAISE(ABORT, 'paid amount Error') ;
		END;
	
