	--###Begin 2025-01 prevent delete customers fk---
	
		CREATE TRIGGER if not EXISTS invalid_delete_customers
		BEFORE delete ON customers
		FOR EACH ROW
		WHEN (
		exists (select 1 from transactions where cus_id=OLD.id)
		or exists(select 1 from transactions where t_cus_id is not null and t_cus_id=OLD.id)
		or exists(select 1 from bills where cus_id is not null and cus_id=OLD.id)
		or exists(select 1 from bills2 where cus_id is not null and cus_id=OLD.id)
		)
		BEGIN
		SELECT RAISE(ABORT, 'Invalid Delete Customer') ;
		END;
	
	
		CREATE TRIGGER if not EXISTS invalid_delete_customers_h
		BEFORE delete ON customers
		FOR EACH ROW
		WHEN (
		exists (select 1 from transactions_h where cus_id=OLD.id)
		or exists(select 1 from transactions_h where t_cus_id is not null and t_cus_id=OLD.id)
		or exists(select 1 from bills_h where cus_id is not null and cus_id=OLD.id)
		or exists(select 1 from bills2_h where cus_id is not null and cus_id=OLD.id)
		)
		BEGIN
		SELECT RAISE(ABORT, 'Invalid Delete Customer h') ;
		END;
	
