    insert or ignore into z_status (id,name) values(2,'CLEARED');
    insert or ignore into z_status (id,name) values(3,'REPORTED+Warning');
    insert or ignore into z_status (id,name) values(4,'CLEARED+Warning');
    insert or ignore into z_status (id,name) values(-1,'NOT_REPORTED');
    insert or ignore into z_status (id,name) values(-2,'NOT_CLEARED');
    insert or ignore into z_status (id,name) values(-3,'Failed');
    insert or ignore into z_status (id,name) values(-4,'Error');
    update z_status set name='REPORTED+' where id=3;
